import codecs
seen = []
def recover(error):
    seen.append(error)
    decoder.errors = 'strict'
    return ('?', -1)
codecs.register_error('initial-fault', recover)
decoder = codecs.getincrementaldecoder('gb2312')('initial-fault')
try:
    decoder.decode(b'\xff\xff', True)
except UnicodeDecodeError as error:
    print(error.args)
    print(error.start, error.end, error.reason, error is seen[0])
try:
    decoder.decode(b'A\xff', True)
except UnicodeDecodeError as error:
    print(error.args)
    print(error.start, error.end, error.reason, error is seen[0])

